<?php
// SPDX-License-Identifier: AGPL-3.0-or-later
//
// GhulSuite server module – storage and shares on any web hosting with PHP 8.1+, no database.
//
// This file is generated by the GhulSuite app with its own access key; do not edit by hand.
// Everything it stores is encrypted on the device before upload: vaults, GhulDrive blocks and
// shared files. The server only ever sees ciphertext.
//
//   POST ?a=…   storage API for the app (HMAC-signed requests, time window, one-time nonces)
//   GET  ?s=ID  a shared package (expiry, download limit and one-time links enforced here)
//   GET         the page that decrypts a share in the recipient's browser

declare(strict_types=1);

const GHUL_VERSION = 1;
const GHUL_KEY = '__GHUL_KEY__';
const GHUL_DATA = '__GHUL_DATA__';
const GHUL_VIEWER_HTML = '__GHUL_VIEWER_HTML__';
const GHUL_VIEWER_JS = '__GHUL_VIEWER_JS__';
const GHUL_VIEWER_CSS = '__GHUL_VIEWER_CSS__';
const GHUL_MAX_SKEW = 300;
const GHUL_MAX_FAILS = 20;

header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: no-referrer');
header('X-Robots-Tag: noindex, nofollow');
header('Cache-Control: no-store');
header('X-Frame-Options: DENY');

function ghul_fail(int $code, string $msg = ''): never
{
    http_response_code($code);
    header('Content-Type: text/plain; charset=utf-8');
    echo $msg;
    exit;
}

function ghul_json(mixed $value): never
{
    header('Content-Type: application/json');
    echo json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    exit;
}

/** The data folder: random name next to this file, closed for web access. */
function ghul_dir(string $sub = ''): string
{
    $base = str_starts_with(GHUL_DATA, '/') ? GHUL_DATA : __DIR__ . '/' . GHUL_DATA;
    if (!is_dir($base)) {
        if (!@mkdir($base, 0700, true)) {
            ghul_fail(500, 'data folder not writable');
        }
        file_put_contents($base . '/.htaccess', "Require all denied\nDeny from all\n");
        file_put_contents($base . '/index.html', '');
    }
    $dir = $sub === '' ? $base : $base . '/' . $sub;
    if (!is_dir($dir)) {
        @mkdir($dir, 0700, true);
    }
    return $dir;
}

/** Allows only plain relative paths: no "..", no ".", no control characters. */
function ghul_path(string $p, bool $allowEmpty = false): string
{
    if ($p === '') {
        if ($allowEmpty) {
            return '';
        }
        ghul_fail(400, 'path required');
    }
    if (strlen($p) > 1024 || preg_match('/[\x00-\x1f\\\\]/', $p)) {
        ghul_fail(400, 'invalid path');
    }
    foreach (explode('/', $p) as $seg) {
        if ($seg === '' || $seg === '.' || $seg === '..' || !preg_match('/^[\p{L}\p{N} ._()+\-]+$/u', $seg)) {
            ghul_fail(400, 'invalid path');
        }
        // Even with the key nothing executable or server configuration can be placed here.
        if (preg_match('/\.(php\d?|phtml|phar|pht|phps|cgi|pl|py|sh|shtml)$/i', $seg) || preg_match('/^\.(htaccess|htpasswd|user\.ini)$/i', $seg)) {
            ghul_fail(400, 'file type not allowed');
        }
    }
    return $p;
}

function ghul_share_id(string $id): string
{
    if (!preg_match('/^[0-9a-f]{32}$/', $id)) {
        ghul_fail(404);
    }
    return $id;
}

/** Writes atomically: temporary file in the same folder, then rename. */
function ghul_write(string $file, string $data, int $flags = 0): void
{
    $dir = dirname($file);
    if (!is_dir($dir) && !@mkdir($dir, 0700, true)) {
        ghul_fail(500, 'cannot create folder');
    }
    $tmp = $dir . '/.tmp-' . bin2hex(random_bytes(8));
    if (file_put_contents($tmp, $data, $flags) === false || !rename($tmp, $file)) {
        @unlink($tmp);
        ghul_fail(500, 'cannot write');
    }
}

/** Counts failed logins per address; too many in ten minutes block the address for a while. */
function ghul_fails(bool $add): void
{
    $file = ghul_dir('fails') . '/' . hash('sha256', ($_SERVER['REMOTE_ADDR'] ?? '') . GHUL_KEY);
    $now = time();
    $list = is_file($file) ? array_filter(explode(',', (string) file_get_contents($file)), fn ($t) => (int) $t > $now - 600) : [];
    if ($add) {
        $list[] = (string) $now;
        file_put_contents($file, implode(',', $list), LOCK_EX);
    }
    if (count($list) >= GHUL_MAX_FAILS) {
        ghul_fail(429, 'too many failed attempts');
    }
}

/** Canonical query of the signed parameters. */
function ghul_canonical(): string
{
    $keys = ['a', 'p', 'id', 'exp', 'max', 'n'];
    $parts = [];
    foreach ($keys as $k) {
        if (isset($_GET[$k])) {
            $parts[] = $k . '=' . rawurlencode((string) $_GET[$k]);
        }
    }
    return implode('&', $parts);
}

function ghul_auth(string $body): void
{
    ghul_fails(false);
    $time = $_SERVER['HTTP_X_GHUL_TIME'] ?? '';
    $nonce = $_SERVER['HTTP_X_GHUL_NONCE'] ?? '';
    $sig = $_SERVER['HTTP_X_GHUL_SIG'] ?? '';
    if (!ctype_digit($time) || abs(time() - (int) $time) > GHUL_MAX_SKEW || !preg_match('/^[0-9a-f]{32}$/', $nonce)) {
        ghul_fails(true);
        ghul_fail(401, 'invalid request time');
    }
    $msg = "ghul/v1\n" . $_SERVER['REQUEST_METHOD'] . "\n" . ghul_canonical() . "\n" . $time . "\n" . $nonce . "\n" . hash('sha256', $body);
    $expected = hash_hmac('sha256', $msg, (string) hex2bin(GHUL_KEY));
    if (!hash_equals($expected, $sig)) {
        ghul_fails(true);
        ghul_fail(401, 'invalid signature');
    }
    // Each nonce works once (replay protection); old nonces are cleaned up now and then.
    $nonces = ghul_dir('nonces');
    $h = @fopen($nonces . '/' . $nonce, 'x');
    if ($h === false) {
        ghul_fail(401, 'request replayed');
    }
    fclose($h);
    if (random_int(0, 49) === 0) {
        foreach (glob($nonces . '/*') ?: [] as $f) {
            if (filemtime($f) < time() - 2 * GHUL_MAX_SKEW) {
                @unlink($f);
            }
        }
    }
}

function ghul_cleanup_shares(string $keep = ''): void
{
    $dir = ghul_dir('shares');
    $now = (int) (microtime(true) * 1000);
    foreach (glob($dir . '/*.json') ?: [] as $f) {
        if ($keep !== '' && basename($f, '.json') === $keep) {
            continue; // the share being requested answers "expired" itself
        }
        $m = json_decode((string) file_get_contents($f), true);
        if (is_array($m) && ($m['exp'] ?? 0) > 0 && $m['exp'] < $now) {
            @unlink(substr($f, 0, -5) . '.bin');
            @unlink($f);
        }
    }
    foreach (glob($dir . '/*.part') ?: [] as $f) {
        if (filemtime($f) < time() - 86400) {
            @unlink($f);
        }
    }
}

/** GET ?s=ID: streams a share if it is still valid; counts downloads under a lock. */
function ghul_serve_share(string $id): never
{
    $dir = ghul_dir('shares');
    $meta = $dir . '/' . $id . '.json';
    $bin = $dir . '/' . $id . '.bin';
    $h = @fopen($meta, 'c+');
    if ($h === false || !is_file($bin)) {
        if ($h) {
            fclose($h);
            @unlink($meta);
        }
        ghul_fail(404);
    }
    flock($h, LOCK_EX);
    $m = json_decode((string) stream_get_contents($h), true);
    if (!is_array($m)) {
        flock($h, LOCK_UN);
        fclose($h);
        ghul_fail(404);
    }
    $now = (int) (microtime(true) * 1000);
    $expired = ($m['exp'] ?? 0) > 0 && $m['exp'] < $now;
    $used = ($m['max'] ?? 0) > 0 && ($m['count'] ?? 0) >= $m['max'];
    if ($expired || $used) {
        @unlink($bin);
        flock($h, LOCK_UN);
        fclose($h);
        @unlink($meta);
        ghul_fail(410);
    }
    $m['count'] = ($m['count'] ?? 0) + 1;
    $last = ($m['max'] ?? 0) > 0 && $m['count'] >= $m['max'];
    ftruncate($h, 0);
    rewind($h);
    fwrite($h, (string) json_encode($m));
    fflush($h);
    header('Content-Type: application/octet-stream');
    header('Content-Length: ' . filesize($bin));
    readfile($bin);
    if ($last) {
        @unlink($bin);
        flock($h, LOCK_UN);
        fclose($h);
        @unlink($meta);
    } else {
        flock($h, LOCK_UN);
        fclose($h);
    }
    exit;
}

function ghul_viewer(): never
{
    header("Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'");
    $v = $_GET['v'] ?? '';
    if ($v === 'js') {
        header('Content-Type: text/javascript; charset=utf-8');
        echo base64_decode(GHUL_VIEWER_JS);
        exit;
    }
    if ($v === 'css') {
        header('Content-Type: text/css; charset=utf-8');
        echo base64_decode(GHUL_VIEWER_CSS);
        exit;
    }
    header('Content-Type: text/html; charset=utf-8');
    $self = rawurlencode(basename(__FILE__));
    echo str_replace(['href="viewer.css"', 'src="viewer.js"'], ['href="' . $self . '?v=css"', 'src="' . $self . '?v=js"'], base64_decode(GHUL_VIEWER_HTML));
    exit;
}

// --- routing -----------------------------------------------------------------------------------
$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';
if ($method === 'GET' && isset($_GET['s'])) {
    $sid = ghul_share_id((string) $_GET['s']);
    if (random_int(0, 19) === 0) {
        ghul_cleanup_shares($sid);
    }
    ghul_serve_share($sid);
}
if ($method === 'GET' && !isset($_GET['a'])) {
    ghul_viewer();
}
if ($method !== 'POST') {
    ghul_fail(405);
}

$body = (string) file_get_contents('php://input');
ghul_auth($body);
$files = ghul_dir('files');
$a = (string) ($_GET['a'] ?? '');
switch ($a) {
    case 'info':
        ghul_json(['version' => GHUL_VERSION, 'php' => PHP_VERSION, 'free' => @disk_free_space($files) ?: 0]);
    case 'list':
        $p = ghul_path((string) ($_GET['p'] ?? ''), true);
        $dir = $p === '' ? $files : $files . '/' . $p;
        $out = [];
        foreach (is_dir($dir) ? (scandir($dir) ?: []) : [] as $n) {
            if ($n === '.' || $n === '..' || str_starts_with($n, '.tmp-')) {
                continue;
            }
            $f = $dir . '/' . $n;
            $out[] = ['n' => $n, 'd' => is_dir($f), 's' => is_file($f) ? filesize($f) : 0];
        }
        ghul_json($out);
    case 'read':
        $f = $files . '/' . ghul_path((string) ($_GET['p'] ?? ''));
        if (!is_file($f)) {
            ghul_fail(404);
        }
        header('Content-Type: application/octet-stream');
        header('Content-Length: ' . filesize($f));
        readfile($f);
        exit;
    case 'write':
        ghul_write($files . '/' . ghul_path((string) ($_GET['p'] ?? '')), $body);
        ghul_json(true);
    case 'delete':
        $f = $files . '/' . ghul_path((string) ($_GET['p'] ?? ''));
        if (is_file($f)) {
            unlink($f);
        }
        ghul_json(true);
    case 'mkdir':
        $d = $files . '/' . ghul_path((string) ($_GET['p'] ?? ''));
        if (!is_dir($d) && !@mkdir($d, 0700, true)) {
            ghul_fail(500, 'cannot create folder');
        }
        ghul_json(true);
    case 'share_part':
        // Large shares arrive in parts (hosting limits the size of one request).
        $id = ghul_share_id((string) ($_GET['id'] ?? ''));
        $part = ghul_dir('shares') . '/' . $id . '.part';
        $n = (int) ($_GET['n'] ?? 0);
        if ($n === 0) {
            @unlink($part);
        } elseif (!is_file($part)) {
            ghul_fail(409, 'missing earlier parts');
        }
        if (file_put_contents($part, $body, FILE_APPEND | LOCK_EX) === false) {
            ghul_fail(500, 'cannot write');
        }
        ghul_json(true);
    case 'share_done':
        $id = ghul_share_id((string) ($_GET['id'] ?? ''));
        $dir = ghul_dir('shares');
        if (!is_file($dir . '/' . $id . '.part') || !rename($dir . '/' . $id . '.part', $dir . '/' . $id . '.bin')) {
            ghul_fail(409, 'nothing uploaded');
        }
        $meta = ['exp' => max(0, (int) ($_GET['exp'] ?? 0)), 'max' => max(0, (int) ($_GET['max'] ?? 0)), 'count' => 0];
        ghul_write($dir . '/' . $id . '.json', (string) json_encode($meta));
        ghul_json(true);
    case 'share_delete':
        $id = ghul_share_id((string) ($_GET['id'] ?? ''));
        $dir = ghul_dir('shares');
        @unlink($dir . '/' . $id . '.bin');
        @unlink($dir . '/' . $id . '.json');
        @unlink($dir . '/' . $id . '.part');
        ghul_json(true);
    case 'share_list':
        ghul_cleanup_shares();
        $out = [];
        foreach (glob(ghul_dir('shares') . '/*.json') ?: [] as $f) {
            $m = json_decode((string) file_get_contents($f), true);
            if (is_array($m)) {
                $out[] = ['id' => basename($f, '.json'), 'exp' => $m['exp'] ?? 0, 'max' => $m['max'] ?? 0, 'count' => $m['count'] ?? 0];
            }
        }
        ghul_json($out);
    default:
        ghul_fail(400, 'unknown action');
}
